cd /workspace && python3 - <<'PY'
p='submission/src/offline/ReceiveAudit.java'
s=open(p).read()
s=s.replace('''    static final class AckState {
        // Half-open, sorted, disjoint and adjacent-merged.
        List<long[]> ranges = new ArrayList<>();
        final long[] ecn = {0, 0, 0};
    }''','''    static final class AckState {
        // Accepted ranges are kept append-only during the audit.  ACK state is
        // only needed for the final snapshot, so sorting and merging once at the
        // end avoids repeatedly copying an ever-growing interval list.
        final List<long[]> accepted = new ArrayList<>();
        final long[] ecn = {0, 0, 0};
    }''')
s=s.replace('''                if (ackNew[l] != null) st.ack[l].ranges = st.unionAck(st.ack[l].ranges, ackNew[l]);''','''                if (ackNew[l] != null) st.ack[l].accepted.addAll(ackNew[l]);''')
# replace unionAck method with mergeAck that only merges a single raw list
start=s.index('        List<long[]> unionAck(List<long[]> oldRanges, List<long[]> added) {')
end=s.index('        Map<String,Object> result() {', start)
new='''        List<long[]> mergeAck(List<long[]> raw) {
            if (raw.isEmpty()) return Collections.emptyList();
            ArrayList<long[]> all = new ArrayList<>(raw);
            all.sort((x, y) -> Long.compare(x[0], y[0]));
            ArrayList<long[]> merged = new ArrayList<>();
            long s = -1, e = -1;
            for (long[] r : all) {
                if (s < 0) { s = r[0]; e = r[1]; }
                else if (r[0] <= e) { if (r[1] > e) e = r[1]; }
                else { merged.add(new long[]{s, e}); s = r[0]; e = r[1]; }
            }
            if (s >= 0) merged.add(new long[]{s, e});
            return merged;
        }

'''
s=s[:start]+new+s[end:]
# replace result ack loop block references
old='''            for (int i = 0; i < 3; i++) {
                AckState a = ack[i];
                long count = 0;
                for (long[] x : a.ranges) count += x[1] - x[0];
                long prefix = (!a.ranges.isEmpty() && a.ranges.get(0)[0] == 0)
                        ? a.ranges.get(0)[1] : 0;
                ArrayList<Object> ecn = new ArrayList<>();
                for (long v : a.ecn) ecn.add(v);
                ackOut.add(obj("level", LEVEL_NAME[i], "count", count,
                        "intervals", a.ranges.size(), "prefix", prefix,
                        "sha256", shaHexIntervalList(a.ranges), "ecn", ecn));
            }'''
new='''            for (int i = 0; i < 3; i++) {
                AckState a = ack[i];
                List<long[]> ranges = mergeAck(a.accepted);
                long count = 0;
                for (long[] x : ranges) count += x[1] - x[0];
                long prefix = (!ranges.isEmpty() && ranges.get(0)[0] == 0)
                        ? ranges.get(0)[1] : 0;
                ArrayList<Object> ecn = new ArrayList<>();
                for (long v : a.ecn) ecn.add(v);
                ackOut.add(obj("level", LEVEL_NAME[i], "count", count,
                        "intervals", ranges.size(), "prefix", prefix,
                        "sha256", shaHexIntervalList(ranges), "ecn", ecn));
            }'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
